#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<long long> block_sums(max_threads, 0);
    std::vector<long long> block_offsets(max_threads, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt = omp_get_num_threads();

        const int start = (n * tid) / nt;
        const int end   = (n * (tid + 1)) / nt;

        long long local_sum = 0;
        for (int i = start; i < end; ++i) {
            local_sum += x[i];
        }
        block_sums[tid] = local_sum;

        #pragma omp barrier

        #pragma omp single
        {
            long long offset = 0;
            for (int t = 0; t < nt; ++t) {
                block_offsets[t] = offset;
                offset += block_sums[t];
            }
        }

        long long running = block_offsets[tid];
        for (int i = start; i < end; ++i) {
            running += x[i];
            output[i] = static_cast<int>(running);
        }
    }
}
